package com.tradingsimulator.tradingengine; import com.tradingsimulator.model.*; import java.math.BigDecimal; public final class OrderFactory { public Order market(String s,OrderSide side,int q){return new Order(s,side,OrderType.MARKET,q,null);} public Order limit(String s,OrderSide side,int q,BigDecimal p){return new Order(s,side,OrderType.LIMIT,q,p);} public Order stopLoss(String s,OrderSide side,int q,BigDecimal p){return new Order(s,side,OrderType.STOP_LOSS,q,p);} }
